body {
  --bs-btn-font-family: 'Segoe UI',wf_segoe-ui_normal,helvetica,arial,sans-serif;
}
body.visual-sandbox {
  background-color: #ffffff00 !important;
}
body * {
  border-radius: 0 !important;
}
.selectionContainer * {
  white-space: nowrap !important;
}
.btn-check:focus + .btn-secondary,
.btn-secondary:focus {
  box-shadow: none !important;
}
.btn-check:focus + .btn,
.btn:focus {
  outline: 0;
  box-shadow: none !important;
}
.selectionSlicer.container-fluid {
  padding-left: 6px;
  padding-right: 6px;
}
.filterContainer {
  padding-top: 0px;
  padding-bottom: 10px;
  line-height: 1em;
}
.filterContainer .btn-secondary.filterChanged {
  font-weight: bold;
}
.filter .form-check-label {
  width: 100%;
}
.filter {
  padding-right: 10px;
}
.filter .filterButton,
.filter .filterButton i {
  line-height: 1em;
}
.filter .filterButton {
  min-width: 7em;
  text-align: left;
  font-size: 14px;
  white-space: nowrap;
  display: flex;
  justify-content: space-between;
}
.filter .filterButton span {
  padding-right: 6px;
}
.filter .filterButton i {
  text-align: center;
  white-space: nowrap;
  width: 1em;
  height: 1em;
  display: block;
}
.filter .filterButton.filterOpen i {
  -webkit-transform: rotate(180deg);
  -moz-transform: rotate(180deg);
  -ms-transform: rotate(180deg);
  -o-transform: rotate(180deg);
  transform: rotate(180deg);
}
.filter .inner {
  display: block;
  width: calc(100%);
  overflow-x: auto;
  overflow-y: hidden !important;
  white-space: nowrap !important;
  height: 100%;
}
#filterPopup .filterValue {
  display: flex;
  white-space: nowrap;
  line-height: calc(1em + 2px);
  align-items: center;
}
#filterPopup .filterValue input {
  margin: 0;
}
#filterPopup {
  display: none;
  position: absolute;
  top: 2em;
  left: 0;
  z-index: 1000;
}
#filterPopup .filterPopupContent {
  font-size: 14px;
  overflow-y: auto;
  height: 100%;
  display: flex;
  align-items: center;
  padding-left: 4px;
  padding-right: 4px;
  scrollbar-width: thin !important;
}
::-webkit-scrollbar {
  height: 0.75em;
  background-color: lightgray;
}
::-webkit-scrollbar-thumb {
  background: gray;
}
#filterPopup .filterPopupContent label {
  padding-left: 4px;
}
#arrow,
#arrow::before {
  position: absolute;
  width: 8px;
  height: 8px;
  z-index: -1;
}
#arrow::before {
  content: "";
  transform: rotate(45deg);
  background: #333;
}
#filterPopup[data-popper-placement^="top"] > #arrow {
  bottom: -4px;
}
#filterPopup[data-popper-placement^="bottom"] > #arrow {
  top: -4px;
}
#filterPopup[data-popper-placement^="left"] > #arrow {
  right: -4px;
}
#filterPopup[data-popper-placement^="right"] > #arrow {
  left: -4px;
}
.selectionContainer {
  padding: 0;
}
.selectionControls {
  display: flex;
  padding-right: 10px;
  line-height: 1em;
}
.selectionContainer .clearSelection {
  font-size: 14px;
  padding: 4px 0 4px 4px;
  font-weight: inherit;
  min-width: 7em;
  line-height: 1em;
}
.selection {
  display: inline-block;
  padding-right: 10px;
  line-height: 1em;
}
.selection .badge {
  display: flex;
  font-weight: inherit;
  padding: 4px 0 4px 4px;
}
.selectionTitle {
  display: inline-block;
  vertical-align: middle;
  font-size: 14px;
  line-height: calc(1em + 2px);
}
.selectionAction {
  display: inline-block;
}
.selectionAction .btn {
  padding: 0 0 0 4px;
  font-size: 20px;
  line-height: calc(1em + 2px);
  border: none;
  display: flex;
}
.selectionAction .btn i {
  height: 1em;
  display: block;
}
.filterPopupSearch {
  display: flex;
}
.filterPopupSearch i {
  padding-left: 5px;
  padding-right: 5px;
  padding-top: 1px;
  padding-bottom: 1px;
  border: 1px solid black;
  border-radius: 4px !important;
  margin-left: 6px;
  margin-right: 4px;
}
.filterPopupSearch i:hover {
  background-color: grey;
}
.filterPopupSearch #filterPopupSearchFound {
  flex-grow: 1;
  align-items: center;
  display: flex;
}
.filterPopupSearch #filterPopupSearchFound span {
  font-style: italic;
}
.filterPopupSearch input {
  border: 0;
  margin: 0;
  padding: 0 4px 0 4px;
  outline: none;
  width: 8em;
  font-size: 14px;
}
.filterPaging,
.selectionPaging {
  white-space: nowrap;
  line-height: 1em;
  margin-left: auto !important;
  display: flex;
}
.tooManyRows {
  display: inline-block;
  border-radius: 0.5em;
}
.filterPaging button,
.selectionPaging button {
  padding: 3px 6px 3px 6px;
  border: 0;
}
.filterPaging button:focus,
.selectionPaging button:focus {
  background-color: #44546A;
  color: #fff;
}
.filterPaging button:hover,
.selectionPaging button:hover {
  background-color: #5c636a !important;
  color: #fff;
}
.filterPaging button:focus:hover,
.selectionPaging button:focus:hover {
  background-color: #5c636a;
  color: #fff;
}
.filterPaging button#filterPageRight,
.selectionPaging button#selectionPageRight {
  margin-left: 4px;
}
.filterPaging button,
.filterPaging button i,
.filterPaging .tooManyRows i {
  line-height: calc(1em + 2px);
}
.selectionPaging button,
.selectionPaging button i {
  line-height: calc(1em + 2px);
}
.filterPaging button i,
.selectionPaging button i {
  height: 1em;
  width: 1em;
}
.selectionPaging button {
  background-color: #D6DCE5;
  color: #44546A;
}
.noOptions {
  font-style: italic;
}
div.selectionSlicer > span {
  display: inline-block;
  position: absolute;
  top: -10vh;
  color: #777;
  height: 100%;
  font-size: 140vh;
  line-height: 100vh;
  white-space: nowrap;
  font-weight: bold;
  opacity: 0.1;
}
div.selectionSlicer > div {
  position: relative;
  z-index: 100;
}
